/*
 Problem: 3501. Maximize Active Section with Trade II
 Language: cpp
 Runtime: 147 ms (69.01%)
 Memory: 279.3 MB (29.29%)
 Tags: Array, String, Binary Search, Segment Tree
*/
class Solution {
public:
    vector<int> maxActiveSectionsAfterTrade(string s, vector<vector<int>>& q) {
        int n = s.size(), one = ranges::count(s, '1');
        vector<int> l, r;

        for (int i = 0; i < n;) {
            if (s[i] == '0') {
                int j = i;
                while (j < n && s[j] == '0') j++;
                l.push_back(i);
                r.push_back(j - 1);
                i = j;
            } else {
                i++;
            }
        }

        int m = l.size();
        vector<int> val;
        for (int i = 0; i + 1 < m; i++)
            val.push_back(r[i] - l[i] + 1 + r[i + 1] - l[i + 1] + 1);

        vector<vector<int>> st{val};
        for (int k = 1; k * 2 <= (int)val.size(); k <<= 1) {
            auto &pre = st.back();
            vector<int> cur;
            for (int i = 0; i + k < (int)pre.size(); i++)
                cur.push_back(max(pre[i], pre[i + k]));
            st.push_back(move(cur));
        }

        auto qry = [&](int x, int y) {
            int t = bit_width((unsigned)(y - x + 1)) - 1;
            return max(st[t][x], st[t][y - (1 << t) + 1]);
        };

        auto calc = [&](int i, int L, int R) {
            return val[i] - max(0, L - l[i]) - max(0, r[i + 1] - R);
        };

        auto get = [&](int L, int R) {
            if (m < 2) return 0;
            int x = ranges::lower_bound(r, L) - r.begin();
            int y = ranges::upper_bound(l, R) - l.begin() - 2;
            if (x > y) return 0;
            return max({
                calc(x, L, R),
                calc(y, L, R),
                y - x >= 2 ? qry(x + 1, y - 1) : 0
            });
        };

        vector<int> ans;
        for (auto &v : q)
            ans.push_back(one + get(v[0], v[1]));
        return ans;
    }
};
